def clean(df):
    import pandas as pd
    df = df.copy()
    # coerce numeric columns that may be stored as text
    for col in ['bill_length_mm','bill_depth_mm','flipper_length_mm','body_mass_g','year']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')
    # fix negative flipper_length_mm (abs) - also out_of_range 170-235
    if 'flipper_length_mm' in df.columns:
        df['flipper_length_mm'] = df['flipper_length_mm'].abs()
    # fix species case variants: gentoo->Gentoo, adelie->Adelie
    if 'species' in df.columns:
        df['species'] = df['species'].astype(str).str.strip()
        species_map = {'adelie': 'Adelie', 'gentoo': 'Gentoo'}
        df['species'] = df['species'].apply(lambda x: species_map.get(x.lower(), x) if isinstance(x, str) else x)
    # fix island typos: Bisco->Biscoe, Dram->Dream
    if 'island' in df.columns:
        df['island'] = df['island'].astype(str).str.strip()
        island_map = {'Bisco': 'Biscoe', 'Dram': 'Dream'}
        df['island'] = df['island'].replace(island_map)
    # drop exact duplicate rows (keep id column)
    df = df.drop_duplicates()
    return df

def answer(df):
    # count penguins per island after cleaning
    if 'island' not in df.columns:
        return {}
    d = df.dropna(subset=['island'])
    # ensure island is cleaned (in case answer called on raw df)
    # group and count
    counts = d.groupby('island').size()
    # convert to regular dict with int values
    return {str(k): int(v) for k, v in counts.items()}
